using System;
using System.Linq;
using System.Text.Json;
using Deception.Core;
using Deception.PolyModAdapter;
namespace Deception.Tests
{
 public static partial class BlackoutTests
 {
  static PlayerState P(GameState s,byte id)=>Native.Items(s.PlayerStates).Cast<PlayerState>().Single(p=>p.Id==id);
  static GameState Lighthouses()
  {
   var s=Make();s.Lighthouses=true;
   foreach(var p in Native.Items(s.PlayerStates).Cast<PlayerState>()){p.Capital=new(4,p.Id);p.tasks.Add(new());var t=MapDataExtensions.GetTile(s.Map,p.Capital)!;t.owner=p.Id;t.improvement=new(){type=Polytopia.Data.ImprovementData.Type.city,population=4,xp=12,level=5};}
   foreach(var t in s.Map.Tiles.Values.Where(t=>ExploreLightHouseTask.EvaluateTile(t,s)))t.improvement=new(){type=Polytopia.Data.ImprovementData.Type.lighthouse,level=3};
   return s;
  }
  static void LighthouseCast(GameState s,int x,int y){Cast(s,x,y);Drain(s);}
  static void Fresh(GameState s){s.CurrentPlayer=1;var u=Tile(s,1,1).unit!;u.moved=u.attacked=false;}
  static void Drain(GameState s)
  {
   int limit=256;while(s.ActionStack.Count>0&&--limit>0){var a=Native.Items(s.ActionStack).Cast<ActionBase>().Last();switch(a){case ExploreAction e:Execute(s,e);break;case DecreasePopulationAction d:d.Execute(s);new DecreasePopulationReaction(d).Execute(s);break;case IncreasePopulationAction p:p.Execute(s);break;case IncreaseScoreAction i:i.Execute(s);break;case ImprovementLevelUpAction l:l.Execute(s);break;}s.ActionStack.Remove(a);}Check(limit>0,"finite native queue");
  }
  static void Rediscover(GameState s,byte actor=2,bool queued=true)
  {
   s.CurrentPlayer=actor;RefreshSource(s,new EstablishEmbassyAction{PlayerId=actor},()=>ActionUtils.ExploreTile(s,P(s,actor),Tile(s,0,0),queued));Drain(s);
  }
  static ImprovementState Capital(GameState s,byte actor)=>MapDataExtensions.GetTile(s.Map,P(s,actor).Capital)!.improvement!;
  internal static int LighthouseRun(){try{
   Test("L01-multiple-victims-native-population-xp-score-and-level",()=>{var s=Lighthouses();LighthouseCast(s,0,0);foreach(byte a in new byte[]{2,3}){Check(Capital(s,a).population==3&&Capital(s,a).xp==11,"one population and xp withdrawn");Check(P(s,a).score==9985,"native population and discovery score removed");}Check(Capital(s,1).population==4&&P(s,1).score==10000&&Tile(s,0,0).improvement!.level==1,"caster retained, two native lights forgotten");Check(Capital(s,2).level==5,"earned capital levels remain");});
   Test("L02-idempotent-replay-and-repeat-cast",()=>{var s=Lighthouses();var i=Offer(s,0,0);Check(NativeBlackout.TryCommit(s,i,out _,out _),"first");Drain(s);Check(NativeBlackout.TryCommit(s,i,out var retry,out _)&&retry!.AlreadyCommitted,"receipt retry");Fresh(s);LighthouseCast(s,0,0);Check(Capital(s,2).population==3&&P(s,2).score==9985&&Tile(s,0,0).improvement!.level==1,"no duplicate loss");});
   Test("L03-queued-rediscovery-restores-once-per-player",()=>{var s=Lighthouses();LighthouseCast(s,0,0);Rediscover(s);Check(Capital(s,2).population==4&&Capital(s,2).xp==12&&P(s,2).score==10000,"native rewards restore exact values");Check(Capital(s,3).population==3&&Tile(s,0,0).improvement!.level==2,"other victim stays forgotten");Check(!NativeBlackout.Covered(s,2,new(0,0))&&NativeBlackout.Covered(s,3,new(0,0)),"only authorized player uncovered");});
   Test("L04-immediate-rediscovery-gets-missing-native-reward",()=>{var s=Lighthouses();LighthouseCast(s,0,0);Rediscover(s,2,false);Check(Capital(s,2).population==4&&P(s,2).score==10000&&Tile(s,0,0).improvement!.level==2,"immediate source queues one native restore");});
   Test("L05-multiple-cycles-do-not-farm-population-score-or-light-level",()=>{var s=Lighthouses();for(int n=0;n<4;n++){Fresh(s);LighthouseCast(s,0,0);Rediscover(s,2,n%2==0);}Check(Capital(s,2).population==4&&Capital(s,2).xp==12&&P(s,2).score==10000&&Tile(s,0,0).improvement!.level==2,"four cycles net zero");});
   Test("L06-incomplete-eye-count-excludes-forgotten-corners",()=>{var s=Lighthouses();Tile(s,11,7).explorers!.Remove(2);var task=Native.Items(P(s,2).tasks).Cast<TaskBase>().Single();LighthouseCast(s,0,0);Check(ExploreLightHouseTask.Count(s,2)==2&&!task.IsCompleted,"unfinished Eye loses corner");Rediscover(s);Check(ExploreLightHouseTask.Count(s,2)==3&&!task.IsCompleted,"rediscover one still needs last");s.CurrentPlayer=2;ActionUtils.ExploreTile(s,P(s,2),Tile(s,11,7),true);Drain(s);Check(task.IsCompleted,"native final corner earns Eye");});
   Test("L07-earned-eye-and-city-rewards-remain",()=>{var s=Lighthouses();var task=Native.Items(P(s,2).tasks).Cast<TaskBase>().Single();task.IsCompleted=true;task.IsStarted=true;LighthouseCast(s,0,0);Rediscover(s);Check(task.IsCompleted&&task.IsStarted&&Capital(s,2).level==5,"earned rewards persist");Check(!Native.Items(s.ActionStack).OfType<TaskCompletedAction>().Any(),"no second reward");});
   Test("L08-unexplored-victim-gets-no-loss",()=>{var s=Lighthouses();Tile(s,0,0).explorers!.Remove(2);Tile(s,0,0).improvement!.level=2;LighthouseCast(s,0,0);Check(Capital(s,2).population==4&&P(s,2).score==10000,"no prior discovery no debit");Check(Tile(s,0,0).improvement!.level==1,"only prior explorer decremented");});
   Test("L09-no-capital-discovery-score-only",()=>{var s=Lighthouses();P(s,2).Capital=new(-1,-1);LighthouseCast(s,0,0);Check(P(s,2).score==9995,"no capital population debit");Rediscover(s);Check(P(s,2).score==10000,"discovery score symmetry without capital");});
   Test("L10-current-replacement-capital-is-used",()=>{var s=Lighthouses();var old=Capital(s,2);var t=Tile(s,8,3);t.owner=2;t.improvement=new(){type=Polytopia.Data.ImprovementData.Type.city,population=2,xp=6,level=3};P(s,2).Capital=t.coordinates;LighthouseCast(s,0,0);Check(old.population==4&&t.improvement.population==1,"only native current capital loses one");Rediscover(s);Check(t.improvement.population==2,"same current capital restored");});
   Test("L11-foreign-capital-result-fails-before-spend",()=>{var s=Lighthouses();Tile(s,4,2).owner=3;Check(!NativeBlackout.TryOffer(s,1,0,0,out _,out _),"stale foreign capital denied");Check(!Tile(s,1,1).unit!.attacked&&Capital(s,2).population==4,"no native mutation");});
   foreach(string pending in new[]{"population","level","score"})Test("L12-pending-original-reward-"+pending,()=>{var s=Lighthouses();s.ActionStack.Add(pending switch{"population"=>new IncreasePopulationAction(2,new(0,0),P(s,2).Capital),"level"=>new ImprovementLevelUpAction(2,new(0,0)),_=>new IncreaseScoreAction(2,5,new(0,0))});Check(!NativeBlackout.TryOffer(s,1,0,0,out _,out _),"exact pending original reward blocks preflight");Check(Capital(s,2).population==4&&Tile(s,0,0).GetExplored(2),"unchanged");});
   Test("L13-unrelated-native-queue-retained",()=>{var s=Lighthouses();var unrelated=new IncreasePopulationAction(2,new(8,4),P(s,2).Capital);s.ActionStack.Add(unrelated);Cast(s,0,0);Check(s.ActionStack.Contains(unrelated),"unrelated reward remains queued");});
   foreach(string fault in new[]{"score","fog","ledger"})Test("L14-exact-forget-rollback-"+fault,()=>{var s=Lighthouses();var i=Offer(s,0,0);var before=NativeGameStateEnvelope.Get(s)!.Bytes();var explorers=Tile(s,0,0).explorers;Fault.At=fault;Check(!NativeBlackout.TryCommit(s,i,out _,out _),"injected failure rejected");Check(Capital(s,2).population==4&&Capital(s,2).xp==12&&P(s,2).score==10000&&Tile(s,0,0).improvement!.level==3,"exact lighthouse fields restored");Check(ReferenceEquals(explorers,Tile(s,0,0).explorers)&&before.SequenceEqual(NativeGameStateEnvelope.Get(s)!.Bytes())&&!Tile(s,1,1).unit!.attacked,"fog ledger budget restored");});
   foreach(bool queued in new[]{true,false})Test("L15-discovery-rollback-"+queued,()=>{var s=Lighthouses();LighthouseCast(s,0,0);s.CurrentPlayer=2;var task=Native.Items(P(s,2).tasks).Cast<TaskBase>().Single();var tasks=P(s,2).tasks;var old=NativeGameStateEnvelope.Get(s)!.Bytes();if(queued){Write(s,Read(s) with{Discoveries=new[]{new LedgerDiscovery(2,0,0)}});old=NativeGameStateEnvelope.Get(s)!.Bytes();var a=new ExploreAction{PlayerId=2,Coordinates=new(0,0)};s.ActionStack.Add(a);var q=s.ActionStack;Fault.At="lighthouse-reveal";try{Execute(s,a);throw new Exception("expected failure");}catch(System.IO.IOException){}Check(ReferenceEquals(q,s.ActionStack)&&s.ActionStack.Count==1,"exact queued preimage");}else{Fault.At="lighthouse-reveal";try{RefreshSource(s,new EstablishEmbassyAction{PlayerId=2},()=>ActionUtils.ExploreTile(s,P(s,2),Tile(s,0,0),false));throw new Exception("expected failure");}catch(System.IO.IOException){}Check(s.ActionStack.Count==1,"no queued partial restore rewards");}Check(P(s,2).score==9985&&!task.IsCompleted&&!task.IsStarted&&ReferenceEquals(tasks,P(s,2).tasks),"native score and task flags restored");Check(old.SequenceEqual(NativeGameStateEnvelope.Get(s)!.Bytes())&&!Tile(s,0,0).GetExplored(2),"forgotten state restored");});
   foreach(string fault in new[]{"queue-before","queue-after","tasks-before","tasks-after"})Test("L19-partial-discovery-attach-"+fault,()=>{var s=Lighthouses();LighthouseCast(s,0,0);Write(s,Read(s) with{Discoveries=new[]{new LedgerDiscovery(2,0,0)}});var a=new ExploreAction{PlayerId=2,Coordinates=new(0,0)};s.ActionStack.Add(a);var queue=s.ActionStack;var tasks=P(s,2).tasks;var fog=Tile(s,0,0).explorers;NativeBlackoutDiscovery.Explore? scope=null;Exception? error=null;Fault.At=fault;try{NativeBlackoutDiscovery.BeforeExecute(a,s,out scope);}catch(Exception e){error=e;}Check(error is not null,"injected attach failure");NativeBlackoutDiscovery.ExecuteFinished(error,scope);Check(ReferenceEquals(queue,s.ActionStack)&&ReferenceEquals(tasks,P(s,2).tasks)&&ReferenceEquals(fog,Tile(s,0,0).explorers),"exact independent original or staged references restored");Check(P(s,2).score==9985&&NativeBlackout.Covered(s,2,new(0,0)),"no reward or permit consumption");});
   Test("L20-foreign-queue-does-not-keep-discovery-scope",()=>{var s=Lighthouses();LighthouseCast(s,0,0);Write(s,Read(s) with{Discoveries=new[]{new LedgerDiscovery(2,0,0)}});var a=new ExploreAction{PlayerId=2,Coordinates=new(0,0)};s.ActionStack.Add(a);Check(NativeBlackoutDiscovery.BeforeExecute(a,s,out var scope),"scope entered");var foreign=new Il2CppSystem.Collections.Generic.List<ActionBase>();s.ActionStack=foreign;var final=NativeBlackoutDiscovery.ExecuteFinished(new System.IO.IOException("native"),scope);Check(final is AggregateException&&ReferenceEquals(foreign,s.ActionStack),"foreign queue refused without overwrite");Check(!NativeBlackoutDiscovery.MayWrite(s,Tile(s,0,0),2),"scope retired even after rollback failure");});
   Test("L21-publication-failure-restores-earned-task-latch-and-rewards",()=>{var s=Lighthouses();LighthouseCast(s,0,0);Write(s,Read(s) with{Discoveries=new[]{new LedgerDiscovery(2,0,0)}});var a=new ExploreAction{PlayerId=2,Coordinates=new(0,0)};s.ActionStack.Add(a);var queue=s.ActionStack;var snap=NativeGameStateEnvelope.Get(s)!;Check(NativeBlackoutDiscovery.BeforeExecute(a,s,out var scope),"scope entered");a.Execute(s);Fault.At="ledger";Exception? error=null;try{NativeBlackoutDiscovery.AfterExecute(scope);}catch(Exception e){error=e;}NativeBlackoutDiscovery.ExecuteFinished(error,scope);Check(error is not null&&ReferenceEquals(queue,s.ActionStack)&&s.ActionStack.Count==1,"new native reward children retired");Check(!Native.Items(P(s,2).tasks).Cast<TaskBase>().Single().IsCompleted&&snap.Bytes().SequenceEqual(NativeGameStateEnvelope.Get(s)!.Bytes()),"task latch and ledger restored");});
   Test("L16-saved-native-fields-and-permit-restore-in-new-state",()=>{var s=Lighthouses();LighthouseCast(s,0,0);var snap=NativeGameStateEnvelope.Get(s)!;var ledger=Read(s) with{Discoveries=new[]{new LedgerDiscovery(2,0,0)}};var clone=Lighthouses();foreach(byte p in new byte[]{2,3}){Capital(clone,p).population=3;Capital(clone,p).xp=11;P(clone,p).score=9985;}Tile(clone,0,0).improvement!.level=1;Tile(clone,0,0).explorers=new();Tile(clone,0,0).explorers!.Add(1);NativeGameStateEnvelope.Set(clone,snap.Revision,NativeIdentityLedgerCodec.Encode(ledger,snap.Revision));NativeBlackout.Bind(clone);clone.ActionStack.Add(new ExploreAction{PlayerId=2,Coordinates=new(0,0)});Drain(clone);Check(Capital(clone,2).population==4&&P(clone,2).score==10000&&Capital(s,2).population==3,"new state independently restores saved native debt");});
   Test("L17-ordinary-tile-and-old-game-no-population-semantics",()=>{var s=Lighthouses();Cast(s,2,1);Check(Capital(s,2).population==4&&P(s,2).score==10000,"ordinary tile unchanged");s=Lighthouses();s.Lighthouses=false;LighthouseCast(s,0,0);Check(Capital(s,2).population==4&&Tile(s,0,0).improvement!.level==3,"native old-version lighthouse gate retained");});
   Test("L18-score-and-short-underflow-denied-read-only",()=>{var s=Lighthouses();P(s,2).score=14;Check(!NativeBlackout.TryOffer(s,1,0,0,out _,out _),"unsigned score underflow prevented");Check(P(s,2).score==14&&Capital(s,2).population==4,"readonly validation");P(s,2).score=10000;Capital(s,2).population=short.MinValue;Check(!NativeBlackout.TryOffer(s,1,0,0,out _,out _),"signed population underflow prevented");});
   Test("L22-old-inline-native-action-leaves-stale-capital-display",()=>{var s=Lighthouses();var cap=Capital(s,2);new DecreasePopulationAction(2,P(s,2).Capital,0).Execute(s);Check(cap.population==3&&cap.xp==11&&cap.DisplayedPopulation==4&&cap.RenderRefreshes==0,"old path changes authoritative math but omits native reaction");});
   Test("L23-native-dispatch-refreshes-capital-after-queued-debit",()=>{var s=Lighthouses();Cast(s,0,0);Check(Capital(s,2).population==4&&Capital(s,2).DisplayedPopulation==4,"native queued debit has not executed inline");Check(Native.Items(s.ActionStack).OfType<DecreasePopulationAction>().Count()==2,"exact one debit child per victim");Drain(s);Check(Capital(s,2).population==3&&Capital(s,2).DisplayedPopulation==3&&Capital(s,2).RenderRefreshes==1,"authoritative and visible population agree after native reaction");});
   Test("L24-queue-prefix-order-and-no-duplicate-pending-debits",()=>{var s=Lighthouses();var older=new SourceAction{PlayerId=1,Coordinates=new(5,5)};s.ActionStack.Add(older);var original=s.ActionStack;Cast(s,0,0);Check(!ReferenceEquals(original,s.ActionStack)&&s.ActionStack[0]==older&&original.Count==1,"staged queue retains exact old prefix without mutation");Fresh(s);Cast(s,0,0);Check(Native.Items(s.ActionStack).OfType<DecreasePopulationAction>().Count()==2,"repeated covered cast does not enqueue duplicate debit");Drain(s);Check(Capital(s,2).population==3,"each population debit executes once");});
   Test("L25-out-of-order-rediscovery-cannot-award-before-debit",()=>{var s=Lighthouses();Cast(s,0,0);Write(s,Read(s) with{Discoveries=new[]{new LedgerDiscovery(2,0,0)}});var a=new ExploreAction{PlayerId=2,Coordinates=new(0,0)};s.ActionStack.Add(a);var queue=s.ActionStack;NativeBlackoutDiscovery.Explore? scope=null;Exception? error=null;try{NativeBlackoutDiscovery.BeforeExecute(a,s,out scope);}catch(Exception e){error=e;}NativeBlackoutDiscovery.ExecuteFinished(error,scope);Check(error is not null&&ReferenceEquals(queue,s.ActionStack)&&!Tile(s,0,0).GetExplored(2),"pending loss refuses out-of-order direct invocation");Check(!Native.Items(s.ActionStack).OfType<IncreasePopulationAction>().Any(),"no speculative restore reward");s.ActionStack.Remove(a);Drain(s);s.ActionStack.Add(a);Drain(s);Check(Capital(s,2).population==4&&P(s,2).score==10000,"saved permit succeeds once after debit drains");});
   foreach(string fault in new[]{"queue-before","queue-after","fog","ledger"})Test("L26-forget-restores-exact-native-queue-"+fault,()=>{var s=Lighthouses();var intent=Offer(s,0,0);var queue=s.ActionStack;Fault.At=fault;Check(!NativeBlackout.TryCommit(s,intent,out _,out _),"publication failure rejected");Check(ReferenceEquals(queue,s.ActionStack)&&s.ActionStack.Count==0&&Capital(s,2).population==4&&P(s,2).score==10000,"no orphan debit, native math restored");});
   Test("L27-save-reload-pending-native-debit-before-rediscovery",()=>{var s=Lighthouses();Cast(s,0,0);var saved=NativeGameStateEnvelope.Get(s)!;var clone=Lighthouses();foreach(byte actor in new byte[]{2,3}){P(clone,actor).score=9995;clone.ActionStack.Add(new DecreasePopulationAction(actor,P(clone,actor).Capital,0));}Tile(clone,0,0).improvement!.level=1;Tile(clone,0,0).explorers=new();Tile(clone,0,0).explorers!.Add(1);NativeGameStateEnvelope.Set(clone,saved.Revision,saved.Bytes());NativeBlackout.Bind(clone);Drain(clone);Check(Capital(clone,2).population==3&&Capital(clone,2).DisplayedPopulation==3&&P(clone,2).score==9985,"serialized native action applies outstanding loss to reconstructed state");Rediscover(clone);Check(Capital(clone,2).population==4&&P(clone,2).score==10000&&Capital(s,2).population==4,"rediscovery pays once after restored debit, source unchanged");});
   Console.WriteLine(JsonSerializer.Serialize(new{passed=true,cases=Cases.Count,assertions=Assertions,tests=Cases,scope="Production Blackout/lighthouse/discovery with native-shaped population, tasks, score and queued actions; native game not run"}));return 0;
  }catch(Exception e){Console.WriteLine(JsonSerializer.Serialize(new{passed=false,error=e.ToString()}));return 1;}}
 }
 public static class LighthouseTests{public static int Run()=>BlackoutTests.LighthouseRun();}
}
